package.path='extensions/pixel2voxel/?.lua;'..package.path
local V=require('core.volume');local G=require('core.generate');local R=require('render.raster');local total=0
local red,green,blue=0xff0000ff,0xff00ff00,0xffff0000
local function eq(a,b) assert(a==b,tostring(a)..' != '..tostring(b)) end
local function test(name,fn) local t=os.clock();fn();total=total+1;print(('PASS %-38s %.3f s'):format(name,os.clock()-t)) end
local function img(w,h,fn) local p={};for y=0,h-1 do for x=0,w-1 do p[#p+1]=string.pack('<I4',fn(x,y)) end end;return {w=w,h=h,rgba=table.concat(p)} end
local function raises(fn,code) local ok,e=pcall(fn);assert(not ok and tostring(e):find(code,1,true),tostring(e)) end
local function opaque(im) local a=0;for i=4,#im.rgba,4 do if im.rgba:byte(i)>0 then a=a+1 end end;return a end
local function render(v,yaw,pitch,k,lit) local view={yaw=yaw,pitch=pitch};return R.render(v,V.surface(v),view,R.layout(v,{view},k),lit) end
test('Lua syntax: all host modules',function() for _,p in ipairs({'main.lua','host/images.lua','ui/workspace.lua'}) do assert(loadfile('extensions/pixel2voxel/'..p)) end end)
test('Extrude crop, occupancy, color',function() local v=G.extrude(img(5,4,function(x,y) return x==1 and y==2 and red or x==2 and y==1 and green or 0 end),{depth=3});eq(v.w,2);eq(v.h,2);eq(v.d,3);eq(v.count,6);eq(v.sample(0,0,2,1),red);eq(v.sample(1,1,0,2),green);eq(#V.surface(v),28) end)
test('Stack empty layer + XZ orientation',function() local v=G.stack({img(3,2,function(x,y)return x==2 and y==1 and blue or 0 end),img(3,2,function()return 0 end),img(3,2,function(x,y)return x==0 and y==0 and red or 0 end)},{});eq(v.h,3);eq(v.count,2);assert(V.has(v,2,0,1));assert(V.has(v,0,2,0));assert(not V.has(v,2,1,1));eq(v.sample(2,0,1,6),blue) end)
test('Six-view face color and cube',function() local v=G.hull(img(12,2,function(x)return 0xff000000|(x//2+1) end),{});eq(v.count,8);eq(#V.surface(v),24);for f=1,6 do eq(v.sample(0,0,0,f),0xff000000|f) end end)
test('Asymmetric six-view reconstruction',function() local coords={{1,2,0},{2,0,1},{0,1,2}};local function fcoord(f,x,y,z) if f==1 then return x,2-y elseif f==2 then return 2-z,2-y elseif f==3 then return 2-x,2-y elseif f==4 then return z,2-y elseif f==5 then return x,z else return x,2-z end end;local sheet=img(18,3,function(u,v) local f=u//3+1;for _,c in ipairs(coords) do local x,y=fcoord(f,table.unpack(c));if u%3==x and v==y then return 0xff000000|f end end;return 0 end);local vol=G.hull(sheet,{});eq(vol.count,3);for _,c in ipairs(coords) do assert(V.has(vol,table.unpack(c))) end end)
test('Alignment flip/offset and clipping',function() local sheet=img(18,3,function(x,y)return x%3==0 and y==0 and red or 0 end);local a=G.defaultAlignment();a[1].fh=true;a[1].dx=-1;a[1].dy=1;local f=G.aligned(sheet,a);eq(G.pixel(f[1],1,1),red);eq(G.pixel(f[1],0,0),0);a[2].slot=1;raises(function()G.aligned(sheet,a)end,'E_DUP_FACE') end)
test('Invalid inputs and volume limit',function() raises(function()G.hull(img(7,1,function()return red end),{})end,'E_LAYOUT');raises(function()G.hull(img(6,1,function(x)return x==0 and 0 or red end),{})end,'E_EMPTY_FACE');raises(function()G.extrude(img(1,1,function()return 0x800000ff end),{})end,'E_ALPHA');raises(function()G.extrude(img(1,1,function()return 0 end),{})end,'E_EMPTY_MODEL');raises(function()V.new(1024,1024,2)end,'E_LIMIT_VOLUME');raises(function()G.stack({img(1,1,function()return 0 end)}, {})end,'E_EMPTY_MODEL') end)
test('Orthographic odd dimensions / fidelity',function() for w=1,5 do local v=G.extrude(img(w,3,function()return red end),{depth=2});local b=render(v,0,0,1,false);eq(opaque(b),w*3);for i=1,#b.rgba,4 do local c=string.unpack('<I4',b.rgba,i);assert(c==0 or c==red) end;eq(opaque(render(v,90,0,1,false)),6);eq(opaque(render(v,0,-90,1,false)),w*2) end end)
test('Directional colors in six canonical views',function() local v=G.hull(img(6,1,function(x)return 0xff000000|(x+1) end),{});local poses={{0,0},{90,0},{180,0},{-90,0},{0,-90},{0,90}};for f,p in ipairs(poses) do local b=render(v,p[1],p[2],2,false);eq(opaque(b),4);for i=1,#b.rgba,4 do local c=string.unpack('<I4',b.rgba,i);assert(c==0 or c==(0xff000000|f)) end end end)
test('Stable multi-angle layout and determinism',function() local v=G.extrude(img(7,4,function(x,y)return x<=y and red or blue end),{depth=3});local views={};for i=0,15 do views[#views+1]={yaw=i*22.5,pitch=-30} end;local l=R.layout(v,views,2);local f=V.surface(v);for _,p in ipairs(views) do local a=R.render(v,f,p,l,false);eq(a.w,l.w);eq(a.h,l.h);assert(opaque(a)>0);eq(a.rgba,R.render(v,f,p,l,false).rgba) end end)
test('Cooperative yield/resume equality',function() local im=img(32,32,function()return green end);local count=0;local co=coroutine.create(function()return G.extrude(im,{depth=8},function() count=count+1;if count%3==0 then coroutine.yield() end end)end);local res;repeat local ok,r=coroutine.resume(co);assert(ok,r);res=r until coroutine.status(co)=='dead';eq(res.count,8192);assert(count>3) end)
local file=io.open('extension-tests/benchmark.rgba','rb');if file then local data=file:read('*a');file:close();test('Original benchmark (local only)',function() local v=G.hull({w=192,h=32,rgba=data},{});eq(v.w,20);eq(v.h,22);eq(v.d,12);eq(v.count,5124);eq(#V.surface(v),2054);local b=render(v,-45,-30,2,false);assert(opaque(b)>0) end) end
print('PASS TOTAL '..total)
